        return [(a + d) / 2 + math.sqrt((a + d)**2 - 4 * (a*d - b*c)) / 2,
                (a + d) / 2 - math.sqrt((a + d)**2 - 4 * (a*d - b*c)) / 2]
    A_bar = [[0] * n for _ in range(n)]
